using System.ComponentModel.DataAnnotations;

namespace Saas.Data.Models;

/// <summary>Base for every non-Identity entity.</summary>
public abstract class BaseEntity
{
    /// <summary>
    /// Generated by the application, not the database.
    /// </summary>
    /// <remarks>
    /// Two reasons. Version 7 UUIDs are time-ordered, so they append to the end
    /// of a B-tree instead of scattering writes across it the way v4 does.
    /// More importantly, creating an organization has to set
    /// <c>app.organization_id</c> to the new id <em>before</em> inserting the
    /// owner's membership row, or the row-level security check rejects it --
    /// which is only possible if the id is known up front.
    /// </remarks>
    [Key]
    public Guid Id { get; set; } = Guid.CreateVersion7();

    /// <summary>Set by the database (<c>now()</c>), not the application clock.</summary>
    public DateTimeOffset CreatedDate { get; set; }

    public DateTimeOffset? ModifiedDate { get; set; }
}
